import {actionMenu} from './action-menus.js';
import {icon} from './icons.js';
import {html,t as tr} from './i18n.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?Number(n.toPrecision(5)).toLocaleString():'—';
export const ML_ALGORITHMS={extra_trees:'Extra Trees',random_forest:'Random Forest',hist_gradient_boosting:'HistGradientBoosting',gradient_boosting:'Gradient Boosting',ridge:'Ridge 岭回归',elastic_net:'Elastic Net',svr:'SVR 支持向量回归',mlp:'MLP 神经网络'};
export function trainingControls(settings,engine){return `<div class="prediction-engine-status" role="status">${engine?.ready?`成熟库引擎已就绪 · scikit-learn ${esc(engine.versions['scikit-learn'])} · Python ${esc(engine.python)}`:esc(engine?.error||'正在检查机器学习运行环境…')}</div><div class="prediction-grid"><label>预测场景<select name="inputMode"><option value="composition" ${settings.inputMode==='composition'?'selected':''}>新配方筛选 · 只用成分</option><option value="process" ${settings.inputMode==='process'?'selected':''}>成分 + 已知工艺与测试条件</option><option value="all" ${settings.inputMode==='all'?'selected':''}>全部字段 · 包含已测组织（高级）</option></select></label><label>性能建模尺度<select name="targetScale"><option value="auto" ${settings.targetScale==='auto'?'selected':''}>按性能选择 · Hc 用对数，其余用原单位</option><option value="raw" ${settings.targetScale==='raw'?'selected':''}>原单位 · 关注绝对误差</option><option value="log" ${settings.targetScale==='log'?'selected':''}>自然对数 · 关注倍数误差（须全部大于零）</option></select></label></div><p class="prediction-help">先说明预测时已知哪些信息。仅成分模型用于筛选；已知工艺模式不自动使用晶粒或物相。对数模型仍输出原单位数值与倍数误差带。</p><details><summary>高级设置 · 候选算法与计算参数</summary><fieldset><legend>候选算法 · 通过内层验证选择</legend><div class="prediction-property-choices">${Object.entries(ML_ALGORITHMS).map(([id,label])=>`<label class="prediction-check"><input name="algorithm" type="checkbox" value="${id}" ${settings.algorithms.includes(id)?'checked':''}>${label}</label>`).join('')}</div></fieldset><div class="prediction-grid"><label>配方特征<select name="descriptorMode"><option value="auto" ${settings.descriptorMode==='auto'?'selected':''}>自动比较 · 推荐</option><option value="fractions" ${settings.descriptorMode==='fractions'?'selected':''}>仅原始元素配比</option><option value="alloy" ${settings.descriptorMode==='alloy'?'selected':''}>原始配比 + 合金描述符</option></select></label><label>参数搜索<select name="search"><option value="standard" ${settings.search==='standard'?'selected':''}>标准搜索</option><option value="thorough" ${settings.search==='thorough'?'selected':''}>全面搜索 · 更多参数组合</option></select></label><label>集成树数量<input name="trees" type="number" min="32" max="2048" value="${settings.trees}"></label><label>计算线程<input name="threads" type="number" min="1" max="32" value="${settings.threads}"></label><label>随机种子<input name="seed" type="number" min="0" max="2147483647" value="${settings.seed}"></label></div></details>`;}
function chart(points,residual=false){
 if(!points.length)return'';
 const sample=points.filter((_,i)=>i%Math.max(1,Math.ceil(points.length/1000))===0);
 const xs=sample.map(p=>residual?p.predicted:p.actual),ys=sample.map(p=>residual?p.actual-p.predicted:p.predicted);
 const extent=values=>{let lo=Math.min(...values),hi=Math.max(...values);if(lo===hi){lo--;hi++;}const pad=(hi-lo)*.05;return[lo-pad,hi+pad];};
 const [xl,xh]=extent(residual?xs:[...xs,...ys]),[yl,yh]=residual?extent([...ys,0]):[xl,xh];
 const x=v=>50+(v-xl)/(xh-xl)*330,y=v=>210-(v-yl)/(yh-yl)*180;
 return`<figure class="prediction-chart"><figcaption>${residual?'折外残差 · 横轴预测值，纵轴实测 − 预测':'折外预测 · 横轴实测值，纵轴预测值'}</figcaption><svg viewBox="0 0 410 245" role="img" aria-label="${residual?'残差图':'实测与预测散点图'}"><path d="M50 20V210H390" fill="none" stroke="currentColor" opacity=".4"/><line x1="50" y1="${residual?y(0):210}" x2="380" y2="${residual?y(0):30}" stroke="currentColor" stroke-dasharray="5 4" opacity=".5"/>${sample.map((p,i)=>`<circle cx="${x(xs[i])}" cy="${y(ys[i])}" r="3" fill="var(--accent,#5278bf)" opacity=".65"><title>实测 ${num(p.actual)} · 预测 ${num(p.predicted)} · 第 ${p.fold||'—'} 折</title></circle>`).join('')}<text x="50" y="230" fill="currentColor" font-size="11">${num(xl)}</text><text x="335" y="230" fill="currentColor" font-size="11">${num(xh)}</text><text x="2" y="35" fill="currentColor" font-size="11">${num(yh)}</text><text x="2" y="210" fill="currentColor" font-size="11">${num(yl)}</text></svg></figure>`;
}
export function modelReport(m){if(!m)return'';const t=m.training,metrics=m.metrics,chemistry=t?.compositionFeatures;return`<section class="prediction-card prediction-model-report"><div class="prediction-card-title"><h3>${esc(m.property.name)} · 训练报告</h3><div class="prediction-report-actions">${actionMenu('prediction-report-export',tr('导出'),html`<button type="button" data-export-validation="${esc(m.id)}">${icon('table')}导出全部折外结果 CSV</button><button type="button" data-export-report="${esc(m.id)}">${icon('files')}导出完整训练报告 JSON</button>`,{iconName:'download'})}<button class="icon-button" data-prediction-action="close-report" aria-label="${tr('收起')}" title="${tr('收起')}">${icon('close')}</button></div></div><p>${esc(m.estimator||'旧版自实现 Extra Trees')} · ${m.usable?'通过当前验证门槛':'未通过当前验证门槛，未启用'}${t?' · 外层 5 折评估 / 内层 3 折选型调参':''}</p>${workflowReport(m)}${chemistry?`<p class="prediction-help">最终模型输入：${chemistry.mode==='alloy'?'原始配比 + 合金描述符':'原始配比'}${chemistry.selected?.length?' · '+esc(chemistry.selected.join('、')):''}。附加输入由所选预测场景决定，见输入完整性。</p>`:''}<div class="prediction-metrics">${[['MAE',metrics.mae],['RMSE',metrics.rmse],['R²',metrics.r2],[metrics.baselineKind==='median'?'中位数基线 MAE':'均值基线 MAE',metrics.baselineMAE],['P90 绝对误差',metrics.errorP90],['训练秒数',t?.seconds]].map(([label,v])=>`<div><small>${label}</small><strong>${num(v)}</strong></div>`).join('')}</div><div class="prediction-two-col">${chart(m.validationPoints)}${chart(m.validationPoints,true)}</div>${t?`<p class="prediction-help">以下排名的 MAE ${t.targetScale==='log'?'在自然对数尺度计算':'使用原单位'}，来自全部数据上的内层调参，不能替代上方的外层误差。最终模型使用全部有效数据重新拟合；算法和特征筛选在各外层折内部独立进行。</p><div class="prediction-table-wrap"><table><thead><tr><th>候选算法与参数</th><th>内层 MAE ± 折间标准差</th><th>训练 MAE</th></tr></thead><tbody>${t.leaderboard.map(r=>`<tr><td>${esc(JSON.stringify(r.params))}</td><td>${num(r.mae)} ± ${num(r.std)}</td><td>${num(r.trainMAE)}</td></tr>`).join('')}</tbody></table></div><details><summary>折外置换重要性 · 正值表示置换后 MAE 增大</summary>${m.featureImportance.map(f=>`<p>${esc(f.name)}：${num(f.importance)} ± ${num(f.std)}</p>`).join('')}<p class="prediction-help">按各折平均，${t.targetScale==='log'?'单位为自然对数尺度':'单位与目标一致'}。比较合金描述符时，原始配比与派生描述符作为一组置换。该结果用于了解模型对输入的依赖。</p></details><details><summary>复现信息与训练提示</summary><p>环境：${esc(JSON.stringify(m.environment))}</p><p>数据指纹：${esc(t.dataSHA256)}</p><p>最终参数：${esc(JSON.stringify(t.bestParams))}</p><p>设置：${esc(JSON.stringify(t.options))}</p>${t.warnings.map(w=>`<p class="prediction-warning">${esc(w)}</p>`).join('')||'<p>无库级训练警告。</p>'}</details>`:''}</section>`;}

function workflowReport(m){
 const t=m.training,a=t?.dataAudit,log=m.metrics.log;if(!a)return'';
 const scope={composition:'只根据成分筛选',process:'成分、工艺与测试条件',all:'全部已录入字段'}[t.options.inputMode];
 const score=m.metrics.selection;const quality=!m.usable?'暂不建议使用':score.r2<.5?'仅适合初步筛选':'可辅助候选筛选，仍需实验确认';
 return `<div class="prediction-card"><h4>这次模型能说明什么</h4><p><strong>${quality}</strong> · ${esc(scope)}。${t.targetScale==='log'?'Hc 等正值性能按自然对数拟合，优先减小倍数误差。':'按原单位拟合，优先减小绝对误差。'}</p><p>${a.rows} 条实测标签 · ${a.groups} 个独立组 · 最大一组 ${a.largestGroup} 条 · ${a.missingSources} 条缺来源。${t.assessment.passedFolds}/5 折优于中位数基线。</p><p class="prediction-help">${esc(t.assessment.reason)}。筛选提示中的 R²=0.5 是阅读提示，不是材料性能合格标准。</p>${log?`<p>对数尺度 R² ${num(log.r2)} · 对数 MAE ${num(log.mae)} · 90% 历史倍数误差 ×/÷ ${num(log.factorP90)}。下方主表和散点仍使用 ${esc(m.property.unit)}。</p>`:''}<p>各独立组等权平均误差：${num(m.metrics.groupMAE)} ${esc(m.property.unit)}。</p><details><summary>输入完整性与数据限制</summary>${a.featureCoverage.filter(f=>f.present).map(f=>`<p>${esc(f.name)}：${f.present}/${a.rows} 条有记录</p>`).join('')||'<p>没有使用附加工艺或组织输入。</p>'}${a.warnings.map(w=>`<p class="prediction-warning">${esc(w)}</p>`).join('')}</details></div>`;
}

export function trainingInventory(rows,validation='source'){
 const parent=rows.map((_,i)=>i),seen=new Map();const find=i=>{while(parent[i]!==i){parent[i]=parent[parent[i]];i=parent[i];}return i;};
 let missingSources=0;
 rows.forEach((r,i)=>{const sources=(r.source||'').split(' | ').map(v=>v.trim().toLowerCase().replace(/^(?:https?:\/\/(?:dx\.)?doi\.org\/|doi:\s*)/,'')).filter(Boolean);if(!sources.length)missingSources++;
 const c=Object.entries(r.composition).filter(([,v])=>v>0).sort(([a],[b])=>a<b?-1:a>b?1:0).map(([e,v])=>e+':'+Number(v).toFixed(5)).join('|');
 const keys=['c:'+c,...(validation==='source'?sources.map(v=>'s:'+(/^\d+$/.test(v)?(r.datasetId||'')+':reference:':'')+v):[])];
 for(const key of keys){if(seen.has(key))parent[find(i)]=find(seen.get(key));else seen.set(key,i);}
 });
 return {n:rows.length,groups:new Set(rows.map((_,i)=>find(i))).size,missingSources};
}
